import math

def circle_area(r):
    return math.pi * r ** 2

from math import sqrt

def hypotenuse(a, b):
    return sqrt(a ** 2 + b ** 2)

from statistics import mean, median, mode

def describe(numbers):
    return {'mean': mean(numbers), 'median': median(numbers), 'mode': mode(numbers)}

from statistics import mean

def above_average(numbers):
    avg = mean(numbers)
    result = []
    for n in numbers:
        if n > avg:
            result.append(n)
    return result

